const snapshot = await tools.browser_snapshot({});
const elements = unwrap(snapshot).elements;
let localityRef = '';
let loadRecordRef = '';

for (const el of elements) {
  if (el.name.toLowerCase().includes('locality')) {
    localityRef = el.ref;
    break;
  }
  if (el.name.toLowerCase().includes('load record')) {
    loadRecordRef = el.ref;
    break;
  }
}

if (!localityRef || !loadRecordRef) {
  return `Found locality: ${localityRef}, Load record: ${loadRecordRef}`;
}

await tools.browser_fill({ref: localityRef, value: '福州'});
const newSnapshot = await tools.browser_snapshot({});
const newElements = unwrap(newSnapshot).elements;

let updatedLoadRecordRef = '';
for (const el of newElements) {
  if (el.name.toLowerCase().includes('load record')) {
    updatedLoadRecordRef = el.ref;
    break;
  }
}

await tools.browser_click({ref: updatedLoadRecordRef});
return `Filled locality and clicked load record (${updatedLoadRecordRef})`;
